using GraphApi.Models.SGR.PerfilMenuBotones;namespace GraphApi.Services.SGR.PerfilMenuBotones{    /// <summary>    /// Define las operaciones de negocio y persistencia para PerfilMenuBotones.    /// </summary>    public interface IPerfilMenuBotonesService    {        /// <summary>        /// Obtiene la lista de PerfilMenuBotones con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadPerfilMenuBotones>> GetPerfilMenuBotones(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de PerfilMenuBotones con filtros opcionales.        /// </summary>        /// <param name="perfilMenuBotonID">Filtro opcional para PerfilMenuBotonID.</param>        /// <param name="perfilID">Filtro opcional para PerfilID.</param>        /// <param name="perfil">Filtro opcional para Perfil.</param>        /// <param name="menuBotonID">Filtro opcional para MenuBotonID.</param>        /// <param name="boton">Filtro opcional para Boton.</param>        /// <param name="accion">Filtro opcional para Accion.</param>        /// <param name="menuID">Filtro opcional para MenuID.</param>        /// <param name="tituloMenu">Filtro opcional para TituloMenu.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetPerfilMenuBotonesDynamic(            int? perfilMenuBotonID,            int? perfilID,            string? perfil,            int? menuBotonID,            string? boton,            string? accion,            int? menuID,            string? tituloMenu,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo PerfilMenuBotone.        /// </summary>        /// <param name="objInput">Datos para crear el PerfilMenuBotone.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadPerfilMenuBotones> CreatePerfilMenuBotones(            clCreatePerfilMenuBotones objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un PerfilMenuBotone.        /// </summary>        /// <param name="objInput">Datos para actualizar el PerfilMenuBotone, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadPerfilMenuBotones?> UpdatePerfilMenuBotones(            clUpdatePerfilMenuBotones objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un PerfilMenuBotone por su ID.        /// </summary>        /// <param name="nPerfilMenuBotonesID">ID del PerfilMenuBotone a eliminar.</param>        Task<bool> DeletePerfilMenuBotones(int nPerfilMenuBotonesID);    }}